import { useState, FormEvent } from 'react';
import {
  JxInputField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeammateForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = EMAIL_RE.test(email);
  const showError = emailTouched && !emailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!emailValid) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: 420 }}>
      {submitted && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          onClose={() => setSubmitted(false)}
        >
          {email} приглашён(а) в команду с ролью «{role}».
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@example.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          helperText={showError ? undefined : 'Мы отправим приглашение на этот адрес'}
          errorText={showError ? 'Похоже, это не адрес почты' : undefined}
        />

        <JxSelect
          label="Роль"
          value={role}
          onValueChange={setRole}
          options={[
            { value: 'member', label: 'Участник' },
            { value: 'admin', label: 'Администратор' },
            { value: 'viewer', label: 'Наблюдатель' },
          ]}
        />

        <JxSwitch
          label="Отправить уведомление по почте"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!emailValid}>
          Пригласить
        </JxButton>
      </form>
    </div>
  );
}

